      // ---- Reporting → Audit trail: link to the tamper-evident log
      'auditlog.fromTrail': 'Security actions are also written to the tamper-evident audit log → verify it has not been altered',
      // ---- Documentation → An agent is offline (public/app.js DOCS)
      'docs.expect': 'What to expect',
      'docs.fu.title': 'Update the fleet',
      'docs.fu.lead': 'How new agent code reaches the hosts: one agent, a batch at a time, or the agents asking for it themselves. None of it moves an agent until you ask for it.',
      'docs.fu.settingsUpdates': 'Settings → Updates',
      'docs.fu.settingsAgents': 'Settings → Agents',
      'docs.fu.settingsAgentKey': 'Settings → Agent key',
      'docs.fu.offerTitle': 'What is on offer',
      'docs.fu.offerBody': ' is the one place that says what this server runs, what agent version it serves, and whether the vendor has published anything newer. That last part arrives inside the signed licence proof, so it needs no extra outbound connection and nothing on the path can fake it. An agent behind the offered version carries an update badge on Fleet → Deployment.',
      'docs.fu.oneTitle': 'One agent',
      'docs.fu.one1a': 'Open ',
      'docs.fu.one1b': ', click the agent, and press Update in the drawer.',
      'docs.fu.one2': 'The server signs the release for that agent and pushes it down the agent’s own connection. The agent verifies the signature, installs and restarts.',
      'docs.fu.one3': 'The outcome lands on the audit row the click opened — including the reason, when it failed.',
      'docs.fu.queued': 'An agent that is not connected is no longer refused: the command is queued and delivered the moment that agent next dials in. Clicking Update three times leaves one queued command with the newest target, and a queued update expires after 24 hours rather than installing a version two releases old on a host that comes back next month.',
      'docs.fu.rolloutTitle': 'The whole fleet, a batch at a time',
      'docs.fu.rolloutA': 'Two hundred agents should not be two hundred clicks. The rollout in ',
      'docs.fu.rolloutB': ' selects the agents that are actually behind the offered version, so a re-run is safe and converges, and it moves at most one batch per press (',
      'docs.fu.rolloutC': ' sets the size, default 10).',
      'docs.fu.roll1': 'Look first: the rollout says what it would do before it does anything — the offered version, how many agents are behind, and which ones.',
      'docs.fu.roll2': 'Run it with a batch of one as a canary, and look at that agent for a while: connected, reporting, no new findings.',
      'docs.fu.roll3': 'Then continue with the normal batch size until nothing is behind.',
      'docs.fu.rollNote': 'Every agent gets its own audit row, because “the fleet was updated” is not something anyone can act on six weeks later. Offline agents can be queued as part of a rollout; Docker and unmanaged agents are left out rather than pushed to and declined.',
      'docs.fu.askTitle': 'Agents that ask for their own update',
      'docs.fu.askA': 'A laptop that is online for ten minutes a day is never online when you click. With ',
      'docs.fu.askB': ' → Automatic agent updates on (off by default), an agent that finds itself behind asks for the update itself, inside a maintenance window it evaluates in its own local time — a fleet across three time zones cannot have 02:00 decided here.',
      'docs.fu.askNote': 'The setting is a permission, not an instruction: the server re-checks the policy, that the agent really is behind, that its runtime can be restarted, and a 30-minute per-agent cooldown, so a reconnect loop cannot become an update loop. A single host opts out locally with BLUEEYE_AUTO_UPDATE=0.',
      'docs.fu.pushTitle': 'Which agents can be pushed to',
      'docs.fu.colReports': 'The agent reports',
      'docs.fu.colPushed': 'Pushed to?',
      'docs.fu.colHow': 'What happens',
      'docs.fu.yes': 'Yes',
      'docs.fu.no': 'No',
      'docs.fu.pSystemd': 'The service manager restarts it onto the new code.',
      'docs.fu.pWindows': 'A detached command stops and starts the service — a service cannot stop itself and then issue its own start.',
      'docs.fu.pLaunchd': 'The job is kickstarted onto the new code.',
      'docs.fu.pDocker': 'The host rebuilds the image.',
      'docs.fu.pUnmanaged': 'Nothing on the host would restart it — re-run the installer there.',
      'docs.fu.pushNote': 'It is the agent’s own report that decides, not its platform, and the drawer says which one it is.',
      'docs.fu.refusedTitle': 'When an update is refused',
      'docs.fu.colSee': 'What you see',
      'docs.fu.colMeans': 'What it means',
      'docs.fu.colDo': 'What to do',
      'docs.fu.r1f': 'A refused signature, or two key fingerprints that differ',
      'docs.fu.r1v': 'The agent pins a different release key than this server signs with, usually because the key was regenerated after that agent was installed.',
      'docs.fu.r1w': 'Use the Re-pin button the dashboard offers on that refusal; it shows both keys side by side first.',
      'docs.fu.r2f': 'checksum mismatch',
      'docs.fu.r2v': 'Something between this server and the host served older or altered bytes — a cache or a proxy — or the install script on the host is out of date.',
      'docs.fu.r2w': 'Update again: the message names the stale side. If it is the script, re-run the installer one-liner on the host.',
      'docs.fu.r3f': 'A complaint about the clock',
      'docs.fu.r3v': 'A command signature is refused when it is more than five minutes off the agent’s clock.',
      'docs.fu.r3w': 'Fix time on the host (NTP), then update again.',
      'docs.fu.r4f': 'No signing key',
      'docs.fu.r4v': 'This server has no agent signing key, so it cannot sign a release at all.',
      'docs.fu.r4wa': 'Generate one in ',
      'docs.fu.r4wb': ' (admin), then update again.',
      'docs.fu.expect': 'An updated agent reconnects within a minute and its version on Fleet → Deployment matches the offered one. A queued update stays queued, visibly, until the agent dials in. Keep the fleet on one version: two versions means two behaviours to explain.',
      'docs.ao.title': 'An agent is offline',
      'docs.ao.lead': 'An agent shows as disconnected, or dropped off the overview. Work from the server outward.',
      'docs.ao.s1a': 'Open ',
      'docs.ao.s1b': ' and find the agent: offline agents sort to the top with a grey offline badge. An agent that stays offline is also raised as a finding, so it shows in Changes and can alert.',
      'docs.ao.s2a': 'Click its status badge for the ',
      'docs.ao.s2strong': 'connection diagnosis',
      'docs.ao.s2b': ': an explainable verdict (last seen, the last WebSocket close reason, clock skew) that usually names the cause outright.',
      'docs.ao.s3': 'Check whether it is one agent or many. Many agents offline at once points at the server or network side (firewall, DNS, this server restarting); a single agent points at that host.',
      'docs.ao.s4a': 'If the agent is connected but stale, use ',
      'docs.ao.s4strong': 'Force reconnect',
      'docs.ao.s4b': ' in the connection diagnosis (operator+) to make it re-dial the server.',
      'docs.ao.s5a': 'On the host itself, confirm the agent service is running and can reach this server\'s URL and port. Re-running the installer (',
      'docs.ao.s5b': ') repairs a broken systemd install.',
      'docs.ao.lastSeen': 'Last seen',
      'docs.ao.expect1a': 'A healthy agent reports within seconds of connecting and its ',
      'docs.ao.expect1b': ' stays under a minute. ',
      'docs.ao.expect2a': 'Common close reasons: ',
      'docs.ao.expect2b': ' → the agent token was rotated or revoked (re-enrol); ',
      'docs.ao.expect2c': ' → the network path, or the server is down; a large ',
      'docs.ao.skew': 'clock skew',
      'docs.ao.expect2d': ' → fix NTP on the host, it degrades data quality.',
      'docs.ao.relatedA': 'Related: ',
      'docs.ao.relatedB': ' shows server-side connect and disconnect events, and Reporting → Audit trail records each agent online/offline transition.',
      // ---- Transaction tests: failure phase → diagnosis. The English MUST match PHASE_LABELS in src/analysis/transactionAlerts.js (test/txPhaseLabels.test.js)
