      'set.events.bulkMax': 'Maximum events per bulk action',
      'set.events.bulkMax.hint': 'How many events one selection on the Events page may move at a time. Each one costs a read, a guarded write and an audit row, so this bounds the work of a single request — raise it on a server that can take it, lower it if bulk requests are slow. 500 is the default. A larger backlog is cleared with the setting below rather than with a bigger selection.',
      'set.events.bulkAll': 'Allow "all matching" bulk actions',
      'set.events.bulkAll.hint': 'When on, an operator can apply one transition to every event matching the filters they are looking at — one statement, one audit row, no cap. That is what clears a queue longer than the list itself shows. Off = only the events actually selected can be moved, and a backlog has to be worked through in selections of the size above.',
