      'nav.view.auditLog': 'Audit log integrity',
      'auditlog.title': 'Audit log integrity',
      'auditlog.lead': 'The hash-chained audit log, and proof that nobody has rewritten it.',
      'auditlog.info.title': 'About the tamper-evident audit log',
      'auditlog.info.p1': 'Every security-relevant action (logins, user and role changes, settings, severity rules, report exports, topology changes) is written to one log where each entry carries a hash of the entry before it.',
      'auditlog.info.p2': 'Verify chain recomputes every hash from the stored fields. An entry that was edited no longer matches its own hash; an entry that was deleted leaves the next one pointing at a hash that is not there. Either way the first broken entry is named.',
      'auditlog.info.p3': 'This is not the Reporting → Audit trail, which records who did what with repeats folded together. Entries written before hashing was introduced carry no hash and are not part of the chain.',
