      'agentUpdate.refused.reason': 'the agent refused the update — {reason}',
      'agentUpdate.refused.noReason': 'it gave no reason',
      'agentUpdate.refused.wrongKey': 'this agent trusts a different signing key than this server signs with, so it refuses every signed command. Re-pin it \u2014 the dialog that just opened sends it this server\u2019s current key.',
      'agentUpdate.refused.clockSkew': 'the agent refused the update because the command was outside its accepted time window. That is a CLOCK problem, not a key problem \u2014 check the time on the agent host and on this server.',
      'agentUpdate.trustsKey': 'trusts key {fingerprint}',
      'agentUpdate.trustMismatch': 'This agent trusts release key {agent}, and this server signs with {server}. Signed commands (update, delete) will be refused until it is re-pinned.',
      'agentUpdate.refused.unsignedCommand': 'the agent refused the update because this server cannot SIGN commands. Agents from v0.35 accept a privileged command only with a signature made by the release key they pin. Check Settings \u2192 Agent key: if it says the key cannot sign, that is the whole problem.',
      'agentUpdate.unsigned.noKey': 'update sent UNSIGNED — this server has no agent signing key, so it cannot sign a release. An agent that pinned a key refuses an unsigned update. Generate a key under Settings → Agent key.',
      'agentUpdate.unsigned.verifyOnly': 'update sent UNSIGNED — this server only has a release PUBLIC key (AGENT_RELEASE_PUBLIC_KEY), so it can verify releases but not sign them. An agent that pinned a key refuses an unsigned update. Generate a managed key under Settings → Agent key, then re-pin the agent.',
      'agentUpdate.unsigned.undecryptable': 'update sent UNSIGNED — this server holds a signing key it can no longer decrypt (SECRET_ENCRYPTION_KEY / JWT_SECRET changed since it was generated). Delete it and generate a new one under Settings → Agent key, then re-pin the agents.',
      'agentUpdate.unsigned.signFailed': 'update sent UNSIGNED — signing the release failed on this server. See the system log for the reason.',
