      'probe.mtu.unmeasuredReason': 'Nothing was learned about this path: {reason}',
      'probe.mtu.blackholeTitle': 'PMTUD blackhole — large packets are being dropped silently',
      'probe.mtu.blackholeBody': 'Packets above {mtu} bytes disappear at {where} and no ICMP “fragmentation needed” comes back, so the sender is never told to send less. Connections will establish and then stall on their first full-size packet.',
      'probe.mtu.blackholeFix': 'Fix: allow ICMP type 3 code 4 inbound at or before that hop, clamp TCP MSS to {mss} on the tunnel or edge router, or give the whole path the same MTU.',
      'probe.mtu.reducedTitle': 'Reduced path MTU — Path MTU Discovery is working',
      'probe.mtu.reducedBody': 'The path carries {mtu} bytes, reduced at {where}, and the router is sending ICMP “fragmentation needed” as it should. This is expected on a tunnelled path (IPsec, GRE, PPPoE). It only becomes a fault if an application or firewall ignores that ICMP; clamping TCP MSS to {mss} removes the dependency on it.',
      'probe.mtu.okTitle': 'No MTU restriction found',
      'probe.mtu.okBody': 'The path carries {mtu} bytes end to end, the largest size tested.',
