      'lic.info.title': 'License \u2014 what this server is entitled to',
      'lic.info.p1': 'The status is the verdict on the licence proof this server holds: valid, inside its grace window, expired, or never verified at all. It is re-checked every 6 hours; \u201cRe-validate now\u201d does it immediately.',
      'lic.info.p2': 'Grace is an online-only idea \u2014 running on a cached proof while the licence server cannot be reached. An offline licence is a signed file with a validity window instead, and reports no grace.',
      'lic.info.p3': 'The matrix is what every plan includes, not a sales page: it is what an upgrade would actually turn on, and Roadmap marks what is priced in but not built yet.',
      'about.foot': 'Only the changes that moved what the product can do are listed; the full commit-by-commit history lives in CHANGELOG.md in the repository.',
