      'nav.view.pathLocation': 'Path & location',
      'l2p.title': 'Path & location',
      'l2p.lead': 'Where a device is plugged in, and which switches and ports traffic from A to B crosses — with every gap in what the switches report said out loud.',
      'l2p.info.title': 'Path & location — how it is worked out',
      'l2p.info.p1': 'An IP, a MAC, a hostname or agent:<id> is turned into a MAC through the ARP tables the agents (and, where collected, the routers) report, then into a switch port through the switches’ forwarding tables. A MAC is learned on its own access port and on every uplink towards each switch, so the access port is the one with the fewest MACs that does not face another managed switch.',
      'l2p.info.p2': 'The path between two access switches follows the links the switches themselves report over LLDP or CDP. Where two switches both see the endpoints but no link joins them, the path is drawn as two halves with a gap between them: an unmanaged switch or a missing LLDP configuration is in the way.',
      'l2p.info.p3': 'Different VLANs mean traffic is routed, so the L2 path ends at the gateway. When the gateway cannot be found, name it in the gateway field. The inventory below needs the operator role.',
      'l2p.placeholder': 'IP, MAC, hostname or agent:<id>',
      'l2p.fromSearch': 'Where is it plugged in? Open Path & location',
