      'nav.view.coverage': 'Coverage gaps',
      'setup.coverage.lead': 'Wired up is not the same as covered. For the sites, switches, ports and subnets nothing is watching yet, see',
      'coverage.title': 'Coverage gaps',
      'coverage.lead': 'Where this install cannot see: sites, agents, switches, ports, neighbours and subnets nothing monitors — each with the evidence and a next step.',
      'coverage.info.title': 'Coverage gaps — what is not monitored',
      'coverage.info.p1': 'Every row is computed from what the server already stores — agents, sites, polled switches, their ports, forwarding tables and LLDP neighbours, ARP tables, flow records and discovery candidates. Nothing here is ticked by hand, so the list stays true when the network changes.',
      'coverage.info.p2': 'Each gap says what was found, the numbers it was decided on and a suggested next step. A few rules are heuristics and say so: a subnet is a /24, a port with several unknown MACs is probably an unmanaged switch or access point, and a neighbour is recognised the same way the topology map recognises it (by MAC, or by an exact system name).',
      'coverage.info.p3': '“No gaps” only means none of the checks that could run found one. A check whose data could not be read is listed as not checked, never as clean. Admin only: the list is a map of where nobody is looking.',
