      'snmpdev.info.title': 'Switch',
      'snmpdev.info.p1': 'The port table is keyed on the port NAME, not its SNMP index. An index is only stable until the device re-initialises — a reboot can renumber, and inserting a module into a chassis almost always renumbers everything after it — so a table keyed on the index quietly shows one port’s history under another’s name.',
      'snmpdev.info.p2': 'A port that cannot answer says so. “Not supported”, “no speed reported” and “no counters yet” are three different answers, and none of them is zero: zero errors is what rules out a bad cable, and a device that cannot count them has ruled out nothing.',
