      'devlog.title': 'Device log',
      'devlog.info.hero': 'What the network equipment itself said.',
      'devlog.info.title': 'Device log',
      'devlog.info.p1': 'Switches, firewalls and access points log their own faults — a port going down, a spanning-tree topology change, an OSPF neighbour dropping, a DHCP pool running out. An agent on the customer network receives those messages and forwards them here.',
      'devlog.info.p2': 'Start with the severity buttons. A fleet emits thousands of notice-level lines an hour, all of them true; the counts show what each band is hiding, and clicking one narrows the list to that level and everything worse.',
