      // Burst mode: one target, once a second, while somebody is standing in
      // front of the fault. The SENTENCE under the chart is the output — the
      // figures beside it are supporting evidence.
      'burst.info.hero': 'One target, once a second, while the fault is happening.',
      'burst.info.title': 'Burst mode',
      'burst.info.p1': 'Agents report once a minute and the baselines are hourly, so a five-second loss event never reaches the data at all. A burst measures one target once a second for up to two minutes and streams every sample as it is taken.',
      'burst.info.p2': 'The sentence under the chart is the answer. Loss spread evenly across the burst reads as something continuously wrong on the path — congestion, a duplex mismatch, a bad cable. Loss arriving in groups with quiet in between points at something that recurs: a spanning-tree reconvergence, a link renegotiating, a scheduled job.',
      'burst.info.p3': 'A burst is a packet generator, so the length and the rate are capped on the agent as well as here. Nothing is kept beyond the samples, the timings and the verdict.',
      'burst.noAgents': 'No agents are enrolled yet, so there is nowhere to measure from.',
      'burst.form.title': 'Run a burst',
      'burst.form.note': 'Pick the agent closest to the fault. Up to 120 seconds, one sample a second.',
