      'guide.step.monitors': 'Monitors: the checks that are not a browser',
      'guide.monitors.lead': 'Some things break without anybody being told. Mail is accepted by the server and then quietly dropped. Somebody edits DNS and the SPF record loses a sender. The sending address lands on a blacklist. A monitor asks one of those questions on an interval, so you hear it before a customer does.',
      'guide.monitors.what': 'A monitor is not a test: a test drives a browser through a journey, a monitor is one protocol exchange. It needs no worker — it runs in the server itself, so an install with no browser worker still gets every one of these.',
      'guide.monitors.do1': 'Open Monitors and add the mail check: the mail server, the port (587 with STARTTLS is the usual pair), the account it sends as, and the sender and recipient addresses.',
      'guide.monitors.do2': 'Use a mailbox you own as the recipient. This sends a real message, every interval, forever.',
      'guide.monitors.do3': 'Press Check now. You get the answer in seconds, with the time each phase took — and the first check that works is what puts the monitor on its schedule, so a typo in the setup can never page anybody.',
      'guide.monitors.do4': 'Turn on roundtrip and give it the IMAP mailbox the message lands in. That is what turns "the server took it" into "it actually arrived, in 4.1 seconds".',
      'guide.monitors.do5': '"Check every (seconds)" is the whole schedule — a monitor is not scheduled on the Schedules tab. Once the first check has worked it repeats at that interval forever; Pause on the monitor\u2019s page stops it and keeps the history, Delete takes the history with it.',
      'guide.monitors.do6': 'Click any check in the list to see where the time went: the exchange step by step, what the server answered, and — for a round trip — the route the message took through the relays. Above it, each step is charted in its own panel so "it got slower" becomes "the data step got slower", and the steps that move together are named.',
      'guide.monitors.col.check': 'Check',
      'guide.monitors.col.measures': 'It measures',
      'guide.monitors.r1.f': 'Send-only',
      'guide.monitors.r1.v': 'connect → STARTTLS → AUTH → 250',
      'guide.monitors.r1.w': 'Proves the server TOOK the message. A full queue, a rewritten alias and a spam filter all accept first and drop later.',
      'guide.monitors.r2.f': 'Round-trip',
      'guide.monitors.r2.v': 'the same send, then the mailbox',
      'guide.monitors.r2.w': 'Measures delivery end to end, from your send to the receiving server\u2019s own clock. The probe message deletes itself once found.',
      'guide.monitors.r3.w': 'The floor under a monitor\u2019s own interval. 15 minutes is a sensible mail interval; the floor exists so this cannot become a mail bomb.',
      'guide.monitors.count.one': 'One monitor set up.',
      'guide.monitors.count.other': '{count} monitors set up.',
      'guide.monitors.none': 'No monitors yet. The mail check is the one to start with — it is the failure nothing else reports.',
      'guide.monitors.domainsSet': 'Mail probes may only send to: {domains}.',
      'guide.monitors.domainsOpen': 'No recipient domains listed, so a mail monitor may send to any address. An administrator can bound that under Settings → Service Assurance.',
      'guide.monitors.watch': 'A refused login on the probe\u2019s own account reads as "misconfigured", not as an outage — it says nothing about whether real mail is flowing, and it never pages anybody.',
      'guide.monitors.note': 'A monitor watches nothing until it has worked once, and while it waits a failing check opens nothing — setting one up is not an outage. After that: one bad check is not an outage either: a failure has to repeat before an incident opens. A certificate expiring, a record that is gone or an address that is listed opens one straight away — those do not become more true by being checked twice.',
      'guide.unit.seconds': '{n} s',
      'guide.values.row.minInterval': 'How often a monitor may run at most',
      'guide.values.row.mailDomains': 'Domains a mail probe may send to (empty = any)',
      'guide.values.row.monitorRetention': 'How long monitor results are kept',
      'guide.do.monitor.title': 'Create the mail check',
      'guide.do.monitor.help': 'Sends a message through your mail server on a schedule and measures what happened. This creates the send-only depth; open the monitor afterwards to add the mailbox and measure delivery.',
      'guide.do.monitor.go': 'Create monitor',
      'guide.do.monitor.name': 'Name',
      'guide.do.monitor.namePh': 'Customer mail',
      'guide.do.monitor.host': 'Mail server',
      'guide.do.monitor.from': 'Sends as',
      'guide.do.monitor.to': 'Sends to',
      'guide.do.monitor.ok': 'Monitor "{name}" created. Open it and press Check now.',
      'guide.unit.days': '{n} days',
