      // ---- Documentation → An agent is offline (public/app.js DOCS)
      'docs.expect': 'Hvad du kan forvente',
      'docs.fu.title': 'Opdatér flåden',
      'docs.fu.lead': 'Hvordan ny agentkode når værterne: én agent, en gruppe ad gangen, eller ved at agenterne selv beder om den. Intet af det flytter en agent, før du beder om det.',
      'docs.fu.settingsUpdates': 'Indstillinger → Updates',
      'docs.fu.settingsAgents': 'Indstillinger → Agenter',
      'docs.fu.settingsAgentKey': 'Indstillinger → Agentnøgle',
      'docs.fu.offerTitle': 'Hvad der er tilgængeligt',
      'docs.fu.offerBody': ' er det ene sted, der siger hvad denne server kører, hvilken agentversion den udleverer, og om leverandøren har udgivet noget nyere. Det sidste kommer inde i det signerede licensbevis, så det kræver ingen ekstra udgående forbindelse, og intet i vejen kan forfalske det. En agent, der er bagud for den tilbudte version, bærer et update-mærke på Fleet → Udrulning.',
      'docs.fu.oneTitle': 'Én agent',
      'docs.fu.one1a': 'Åbn ',
      'docs.fu.one1b': ', klik agenten, og tryk Update i panelet.',
      'docs.fu.one2': 'Serveren signerer releasen til netop den agent og skubber den ned gennem agentens egen forbindelse. Agenten kontrollerer signaturen, installerer og genstarter.',
      'docs.fu.one3': 'Resultatet lander på den revisionslinje, klikket åbnede — inklusive årsagen, når det fejlede.',
      'docs.fu.queued': 'En agent, der ikke er forbundet, bliver ikke længere afvist: kommandoen lægges i kø og leveres i samme øjeblik, agenten ringer ind næste gang. Tre klik på Update efterlader én kommando i kø med det nyeste mål, og en opdatering i kø udløber efter 24 timer i stedet for at installere en version, der er to releases gammel, på en vært der kommer tilbage næste måned.',
      'docs.fu.rolloutTitle': 'Hele flåden, en gruppe ad gangen',
      'docs.fu.rolloutA': 'To hundrede agenter bør ikke være to hundrede klik. Udrulningen i ',
      'docs.fu.rolloutB': ' vælger de agenter, der faktisk er bagud for den tilbudte version, så en ny kørsel er sikker og nærmer sig målet, og den flytter højst én gruppe pr. tryk (',
      'docs.fu.rolloutC': ' sætter størrelsen, standard 10).',
      'docs.fu.roll1': 'Se først: udrulningen siger hvad den ville gøre, før den gør noget — den tilbudte version, hvor mange agenter der er bagud, og hvilke.',
      'docs.fu.roll2': 'Kør den med en gruppe på én som kanariefugl, og hold øje med den agent et stykke tid: forbundet, rapporterer, ingen nye fund.',
      'docs.fu.roll3': 'Fortsæt derefter med den normale gruppestørrelse, indtil intet er bagud.',
      'docs.fu.rollNote': 'Hver agent får sin egen revisionslinje, fordi “flåden blev opdateret” ikke er noget, nogen kan bruge til noget seks uger senere. Offline agenter kan lægges i kø som del af en udrulning; Docker-agenter og uadministrerede agenter holdes udenfor i stedet for at få skubbet noget, de afviser.',
      'docs.fu.askTitle': 'Agenter, der selv beder om opdateringen',
      'docs.fu.askA': 'En bærbar, der er online ti minutter om dagen, er aldrig online, når du klikker. Med ',
      'docs.fu.askB': ' → Automatiske agent-opdateringer slået til (fra som standard) beder en agent, der finder sig selv bagud, selv om opdateringen — inden for et vedligeholdelsesvindue, den vurderer i sin egen lokale tid. En flåde fordelt over tre tidszoner kan ikke få 02:00 besluttet her.',
      'docs.fu.askNote': 'Indstillingen er en tilladelse, ikke en instruks: serveren kontrollerer politikken igen, at agenten faktisk er bagud, at dens kørselsmiljø kan genstartes, og en pause på 30 minutter pr. agent, så en genopkoblingsløkke ikke bliver en opdateringsløkke. En enkelt vært siger fra lokalt med BLUEEYE_AUTO_UPDATE=0.',
      'docs.fu.pushTitle': 'Hvilke agenter der kan skubbes til',
      'docs.fu.colReports': 'Agenten rapporterer',
      'docs.fu.colPushed': 'Skubbes der til den?',
      'docs.fu.colHow': 'Hvad der sker',
      'docs.fu.yes': 'Ja',
      'docs.fu.no': 'Nej',
      'docs.fu.pSystemd': 'Servicemanageren genstarter den på den nye kode.',
      'docs.fu.pWindows': 'En løsrevet kommando stopper og starter tjenesten — en tjeneste kan ikke stoppe sig selv og derefter udstede sin egen start.',
      'docs.fu.pLaunchd': 'Jobbet kickstartes på den nye kode.',
      'docs.fu.pDocker': 'Værten bygger billedet igen.',
      'docs.fu.pUnmanaged': 'Intet på værten ville genstarte den — kør installationsprogrammet dér.',
      'docs.fu.pushNote': 'Det er agentens egen rapport, der afgør det, ikke dens platform, og panelet siger hvilken det er.',
      'docs.fu.refusedTitle': 'Når en opdatering bliver afvist',
      'docs.fu.colSee': 'Hvad du ser',
      'docs.fu.colMeans': 'Hvad det betyder',
      'docs.fu.colDo': 'Hvad du gør',
      'docs.fu.r1f': 'En afvist signatur, eller to nøgle-fingeraftryk der er forskellige',
      'docs.fu.r1v': 'Agenten har fastlåst en anden release-nøgle end den, serveren signerer med — typisk fordi nøglen blev oprettet igen efter, at agenten blev installeret.',
      'docs.fu.r1w': 'Brug den Fastlås igen, dashboardet tilbyder ved netop den afvisning; den viser begge nøgler ved siden af hinanden først.',
      'docs.fu.r2f': 'checksum mismatch',
      'docs.fu.r2v': 'Noget mellem denne server og værten udleverede ældre eller ændrede bytes — en cache eller en proxy — eller installationsscriptet på værten er forældet.',
      'docs.fu.r2w': 'Opdatér igen: beskeden udpeger den gamle side. Er det scriptet, så kør installationskommandoen på værten igen.',
      'docs.fu.r3f': 'En klage over uret',
      'docs.fu.r3v': 'En kommandosignatur afvises, når den er mere end fem minutter fra agentens ur.',
      'docs.fu.r3w': 'Ret tiden på værten (NTP), og opdatér så igen.',
      'docs.fu.r4f': 'Ingen signeringsnøgle',
      'docs.fu.r4v': 'Denne server har ingen agent-signeringsnøgle og kan derfor slet ikke signere en release.',
      'docs.fu.r4wa': 'Opret en under ',
      'docs.fu.r4wb': ' (admin), og opdatér så igen.',
      'docs.fu.expect': 'En opdateret agent forbinder igen inden for et minut, og dens version på Fleet → Udrulning svarer til den tilbudte. En opdatering i kø bliver stående i køen, synligt, indtil agenten ringer ind. Hold flåden på én version: to versioner betyder to opførsler at forklare.',
      'docs.ao.title': 'En agent er offline',
      'docs.ao.lead': 'En agent vises som afbrudt eller er forsvundet fra oversigten. Arbejd fra serveren og udad.',
      'docs.ao.s1a': 'Åbn ',
      'docs.ao.s1b': ' og find agenten: offline-agenter sorteres øverst med et gråt offline-mærke. En agent, der bliver ved med at være offline, rejses også som et fund, så den ses under Ændringer og kan alarmere.',
      'docs.ao.s2a': 'Klik på dens statusmærke for ',
      'docs.ao.s2strong': 'forbindelsesdiagnosen',
      'docs.ao.s2b': ': en forklarlig vurdering (senest set, den seneste WebSocket-lukkeårsag, urforskydning), som som regel navngiver årsagen direkte.',
      'docs.ao.s3': 'Tjek om det er én agent eller mange. Mange agenter offline på én gang peger på server- eller netværkssiden (firewall, DNS, denne server genstarter); en enkelt agent peger på den vært.',
      'docs.ao.s4a': 'Hvis agenten er forbundet men forældet, så brug ',
      'docs.ao.s4strong': 'Force reconnect',
      'docs.ao.s4b': ' i forbindelsesdiagnosen (operator+) for at få den til at ringe serveren op igen.',
      'docs.ao.s5a': 'På selve værten: bekræft at agentservicen kører og kan nå denne servers URL og port. At køre installationsprogrammet igen (',
      'docs.ao.s5b': ') reparerer en ødelagt systemd-installation.',
      'docs.ao.lastSeen': 'Senest set',
      'docs.ao.expect1a': 'En sund agent rapporterer inden for få sekunder efter tilslutning, og dens ',
      'docs.ao.expect1b': ' holder sig under et minut. ',
      'docs.ao.expect2a': 'Almindelige lukkeårsager: ',
      'docs.ao.expect2b': ' → agentens token er roteret eller tilbagekaldt (tilmeld igen); ',
      'docs.ao.expect2c': ' → netværksvejen, eller serveren er nede; en stor ',
      'docs.ao.skew': 'urforskydning',
      'docs.ao.expect2d': ' → ret NTP på værten, den forringer datakvaliteten.',
      'docs.ao.relatedA': 'Se også: ',
      'docs.ao.relatedB': ' viser forbindelses- og afbrydelseshændelser på serveren, og Rapportering → Revisionsspor registrerer hver agents online/offline-skift.',
