      'set.events.bulkMax.hint': 'Hvor mange hændelser én markering på Hændelser-siden må flytte ad gangen. Hver koster en læsning, en vagtet skrivning og en revisionslinje, så tallet afgrænser arbejdet i én forespørgsel — hæv det på en server der kan bære det, sænk det hvis masse-forespørgsler er langsomme. 500 er standard. En større bunke ryddes med indstillingen nedenfor frem for med en større markering.',
      'set.events.bulkAll': 'Tillad masse-handlinger på "alt der matcher"',
