      'auditlog.info.p1': 'Alle sikkerhedsrelevante handlinger (logins, bruger- og rolleændringer, indstillinger, alvorlighedsregler, rapporteksporter, topologiændringer) skrives til én log, hvor hver post bærer en hash af posten før den.',
