      'agentUpdate.win.error': 'Kunne ikke danne opdateringskommandoen: {message}',
      'agentUpdate.close': 'Luk',
      'agentUpdate.refused.reason': 'agenten afviste opdateringen \u2014 {reason}',
      'agentUpdate.refused.noReason': 'den angav ingen \u00e5rsag',
      'agentUpdate.refused.wrongKey': 'denne agent har fastl\u00e5st en anden signeringsn\u00f8gle end den, serveren signerer med, og afviser derfor alle signerede kommandoer. Fastl\u00e5s den p\u00e5 ny \u2014 dialogen, der lige \u00e5bnede, sender den serverens nuv\u00e6rende n\u00f8gle.',
      'agentUpdate.refused.clockSkew': 'agenten afviste opdateringen, fordi kommandoen l\u00e5 uden for dens accepterede tidsvindue. Det er et URE-problem, ikke et n\u00f8gleproblem \u2014 tjek tiden p\u00e5 agentens v\u00e6rt og p\u00e5 denne server.',
      'agentUpdate.trustsKey': 'har fastl\u00e5st n\u00f8gle {fingerprint}',
      'agentUpdate.trustMismatch': 'Denne agent har fastl\u00e5st release-n\u00f8gle {agent}, og serveren signerer med {server}. Signerede kommandoer (opdater, slet) afvises, indtil den er fastl\u00e5st p\u00e5 ny.',
      'agentUpdate.refused.unsignedCommand': 'agenten afviste opdateringen, fordi denne server ikke kan SIGNERE kommandoer. Agenter fra v0.35 accepterer kun en privilegeret kommando med en signatur lavet med den release-n\u00f8gle, de har fastl\u00e5st. Se Indstillinger \u2192 Agent-n\u00f8gle: st\u00e5r der, at n\u00f8glen ikke kan signere, er det hele problemet.',
      'agentUpdate.unsigned.noKey': 'opdatering sendt USIGNERET \u2014 denne server har ingen agent-signeringsn\u00f8gle og kan derfor ikke signere en release. En agent med en fastl\u00e5st n\u00f8gle afviser en usigneret opdatering. Opret en n\u00f8gle under Indstillinger \u2192 Agent-n\u00f8gle.',
      'agentUpdate.unsigned.verifyOnly': 'opdatering sendt USIGNERET \u2014 denne server har kun en offentlig release-n\u00f8gle (AGENT_RELEASE_PUBLIC_KEY) og kan verificere, men ikke signere. En agent med en fastl\u00e5st n\u00f8gle afviser en usigneret opdatering. Opret en n\u00f8gle under Indstillinger \u2192 Agent-n\u00f8gle, og fastl\u00e5s derefter agenten p\u00e5 ny.',
      'agentUpdate.unsigned.undecryptable': 'opdatering sendt USIGNERET \u2014 serveren har en signeringsn\u00f8gle, den ikke l\u00e6ngere kan dekryptere (SECRET_ENCRYPTION_KEY / JWT_SECRET er \u00e6ndret siden den blev oprettet). Slet den, opret en ny under Indstillinger \u2192 Agent-n\u00f8gle, og fastl\u00e5s derefter agenterne p\u00e5 ny.',
      'agentUpdate.unsigned.signFailed': 'opdatering sendt USIGNERET \u2014 signeringen af releasen fejlede p\u00e5 denne server. Se systemloggen for \u00e5rsagen.',
