      'usr.noneHint': 'Tilf\u00f8j de folk, der skal logge ind. Navnet er valgfrit og kun til visning \u2014 det er det, brugerloggen viser ud for en handling i stedet for en e-mailadresse.',
      'usr.err.title': 'Brugerlisten kunne ikke l\u00e6ses',
      'usr.info.title': 'Brugere \u2014 konti, roller og f\u00f8rste login',
      'usr.info.p1': 'Tre roller: l\u00e6ser ser, operat\u00f8r opretter og retter, administrator kan det hele, ogs\u00e5 denne side. Serveren h\u00e5ndh\u00e6ver dem; at skjule en knap er kun den anden linje.',
      'usr.info.p2': 'En inviteret konto f\u00e5r en engangskode p\u00e5 mail og skal skifte den ved f\u00f8rste login \u2014 det er det, \u201cafventer f\u00f8rste login\u201d betyder. Invitationer kr\u00e6ver SMTP, og de er sl\u00e5et helt fra, mens SSO/LDAP er aktivt.',
      'usr.info.p3': 'Den indbyggede administrator kan hverken slettes eller f\u00e5 skiftet rolle; kun adgangskoden kan s\u00e6ttes.',
