      'scr.info.p1': '\u00c9n r\u00e6kke pr. integration, alarmkanal og udg\u00e5ende afh\u00e6ngighed. Status er ops\u00e6tningens tilstand, indtil du k\u00f8rer en test; derefter er det, hvad testen fandt.',
      'scr.info.p2': 'Ikke alle m\u00e5l kan testes live \u2014 nogle screenes alene p\u00e5 ops\u00e6tningen, og det siger de. \u201cK\u00f8r fuld screening\u201d tester alt, der kan testes, p\u00e5 \u00e9n gang.',
      'scr.info.p3': 'En r\u00e6kke \u00e5bner, hvad hvert ops\u00e6tningstjek fandt, og hele resultatet af seneste k\u00f8rsel; \u201cS\u00e6t op\u201d f\u00f8rer hen til den sk\u00e6rm, m\u00e5let er konfigureret p\u00e5.',
