      'lic.trust.lead': 'Licensverificeringen er sat forkert op, s\u00e5 \u201cValid\u00e9r p\u00e5 ny\u201d aldrig vil afspejle \u00e6ndringer lavet p\u00e5 licensserveren.',
      'lic.trust.placeholder': 'Den indlejrede offentlige n\u00f8gle i src/license/publicKey.js er stadig pladsholderen, s\u00e5 intet bevis kan nogensinde verificeres. Se docs/licensing.md.',
      'lic.trust.blocked': 'LICENSE_PUBLIC_KEY er sat, men ignoreres i produktion (intet TRUST_ANCHOR_OVERRIDE_ACK), s\u00e5 verificeringen falder tilbage til den indlejrede n\u00f8gle. Se docs/licensing.md.',
      'lic.matrix': 'Hvad hver plan indeholder',
      'lic.matrixNote': 'I er p\u00e5 {plan} \u2014 r\u00e6kker uden for den er d\u00e6mpet',
      'lic.matrixNoteBare': 'R\u00e6kker uden for jeres plan er d\u00e6mpet',
      'lic.matrixFoot': 'Funktioner, der ikke er med i jeres plan, er d\u00e6mpet \u2014 kontakt jeres administrator eller opgrad\u00e9r licensen for at sl\u00e5 dem til. R\u00e6kker m\u00e6rket Roadmap er planlagte og endnu ikke tilg\u00e6ngelige (f\u00f8lges i ROADMAP.md).',
      'lic.col.feature': 'Funktion',
