      'nav.view.pathLocation': 'Sti & placering',
      'l2p.title': 'Sti & placering',
      'l2p.lead': 'Hvor en enhed er tilsluttet, og hvilke switche og porte trafik fra A til B passerer — og hvert hul i det switchene rapporterer, sagt højt.',
      'l2p.info.title': 'Sti & placering — sådan findes den',
      'l2p.info.p1': 'En IP, en MAC, et værtsnavn eller agent:<id> bliver til en MAC via de ARP-tabeller agenterne (og routerne, hvor de indsamles) rapporterer, og derefter til en switchport via switchenes forwarding-tabeller. En MAC læres på sin egen adgangsport og på hvert uplink mod hver switch, så adgangsporten er den med færrest MAC-adresser, som ikke vender mod en anden styret switch.',
      'l2p.info.p2': 'Stien mellem to adgangsswitche følger de forbindelser switchene selv rapporterer via LLDP eller CDP. Hvor to switche begge ser endepunkterne, men ingen forbindelse binder dem sammen, tegnes stien som to halvdele med et hul imellem: en ustyret switch eller manglende LLDP-opsætning står i vejen.',
      'l2p.info.p3': 'Forskellige VLAN betyder, at trafikken routes, så L2-stien ender ved gatewayen. Kan gatewayen ikke findes, så angiv den i gateway-feltet. Inventaret nedenfor kræver operatørrollen.',
      'l2p.placeholder': 'IP, MAC, værtsnavn eller agent:<id>',
