      // Administration -> Dækningshuller (src/coverage/, docs/coverage.md).
      'nav.view.coverage': 'Dækningshuller',
      'setup.coverage.lead': 'Sat op er ikke det samme som dækket. De lokationer, switches, porte og subnet som endnu ingen overvåger, står under',
      'coverage.title': 'Dækningshuller',
      'coverage.lead': 'Hvor denne installation ikke kan se: lokationer, agenter, switches, porte, naboer og subnet som intet overvåger — hver med belæg og et næste skridt.',
      'coverage.info.title': 'Dækningshuller — hvad der ikke overvåges',
      'coverage.info.p1': 'Hver række beregnes ud fra det serveren allerede har gemt — agenter, lokationer, pollede switches, deres porte, forwarding-tabeller og LLDP-naboer, ARP-tabeller, flow-poster og kandidater fra netværksscanning. Intet her krydses af i hånden, så listen forbliver sand når netværket ændrer sig.',
      'coverage.info.p2': 'Hvert hul fortæller hvad der blev fundet, tallene det blev afgjort på og et forslag til næste skridt. Nogle få regler er tommelfingerregler og siger det: et subnet er et /24, en port med flere ukendte MAC-adresser er formentlig en ikke-administreret switch eller et access point, og en nabo genkendes på samme måde som topologikortet genkender den (på MAC eller et eksakt systemnavn).',
      'coverage.info.p3': '“Ingen huller” betyder kun at ingen af de kontroller der kunne køre, fandt et. En kontrol hvis data ikke kunne læses, vises som ikke kontrolleret — aldrig som ren. Kun for administratorer: listen er et kort over hvor ingen kigger.',
