      'burst.info.hero': 'Ét mål, én gang i sekundet, mens fejlen sker.',
      'burst.info.title': 'Burst-tilstand',
      'burst.info.p1': 'Agenter rapporterer én gang i minuttet, og baselines regnes pr. time, så et fem sekunders tab aldrig når frem til data. En burst måler ét mål én gang i sekundet i op til to minutter og sender hver måling videre, mens den tages.',
      'burst.info.p2': 'Sætningen under grafen er svaret. Tab, der er jævnt fordelt over bursten, læses som noget, der er galt hele tiden på vejen — belastning, en duplex-uoverensstemmelse, et dårligt kabel. Tab, der kommer i grupper med ro imellem, peger på noget, der gentager sig: en spanning-tree-omlægning, et link der forhandler igen, et planlagt job.',
      'burst.info.p3': 'En burst er en pakkegenerator, så både længden og hastigheden er begrænset på agenten og ikke kun her. Der gemmes ikke andet end målingerne, tiderne og vurderingen.',
      'burst.noAgents': 'Der er endnu ingen agenter tilmeldt, så der er ikke noget at måle fra.',
