      'guide.on': 'til',
      'guide.off': 'fra',
      'guide.progress': 'Fremdrift i guiden',
      'guide.openTab': 'Åbn {tab}',
      'guide.openSettings': 'Indstillinger → Service Assurance',
      'guide.openAlerting': 'Indstillinger → Alarmering',
      'guide.openDocs': 'Åbn håndbogen',
      'guide.unavailable': 'Guiderne kunne ikke indlæses.',
      'guide.stateUnavailable': 'Kunne ikke læse den aktuelle status ({message}). Alle trin nedenfor gælder stadig — det er kun linjerne om, hvad I allerede har gjort, der mangler.',
      'guide.state.unknown': 'Ikke læst — se noten øverst.',
      'guide.status.done': 'Klar',
      'guide.status.todo': 'Mangler',
      'guide.status.warn': 'Se på det',
      'guide.status.unknown': 'Ukendt',
      'guide.values.title': 'Værdier du skal bruge',
      'guide.unit.ms': '{n} ms',
      'guide.unit.sec': '{n} s',
      'guide.unit.min': '{n} min',
      'guide.step.monitors': 'Målinger: de tjek, der ikke er en browser',
      'guide.monitors.lead': 'Nogle ting går i stykker, uden at nogen får besked. Mailen bliver taget imod af serveren og derefter stille smidt væk. Nogen retter i DNS, og SPF-recorden mister en afsender. Afsenderadressen ender på en blackliste. En måling stiller ét af de spørgsmål med et fast interval, så du hører det før kunden gør.',
      'guide.monitors.what': 'En måling er ikke en test: en test kører en browser gennem en rejse, en måling er én protokoludveksling. Den kræver ingen worker — den kører i serveren selv, så en installation uden browser-worker får dem alle sammen alligevel.',
      'guide.monitors.do1': 'Åbn Målinger og opret mail-tjekket: mailserveren, porten (587 med STARTTLS er det normale par), kontoen den sender som, og afsender- og modtageradresse.',
      'guide.monitors.do2': 'Brug en postkasse, du selv ejer, som modtager. Det her sender en rigtig mail, hvert interval, altid.',
      'guide.monitors.do3': 'Tryk Tjek nu. Du får svaret på sekunder, med tiden for hver fase — og det første tjek, der virker, er det, der sætter målingen på skema, så en tastefejl i opsætningen aldrig kan vække nogen.',
      'guide.monitors.do4': 'Slå roundtrip til og giv den IMAP-postkassen, mailen lander i. Det er det, der gør "serveren tog imod" til "den kom faktisk frem, på 4,1 sekunder".',
      'guide.monitors.do5': '"Tjek hvert (sekunder)" er hele skemaet — en måling planlægges ikke på fanen Planlægning. Når det første tjek har virket, gentager den sig i det interval altid; Sæt på pause på målingens side stopper den og beholder historikken, Slet tager historikken med sig.',
      'guide.monitors.do6': 'Klik på et tjek i listen for at se, hvor tiden gik: udvekslingen trin for trin, hvad serveren svarede, og — ved en rundtur — hvilken vej mailen tog gennem relayene. Ovenover er hvert trin tegnet i sit eget felt, så "den blev langsommere" bliver til "data-trinnet blev langsommere", og de trin, der følges ad, bliver nævnt.',
      'guide.monitors.col.check': 'Tjek',
      'guide.monitors.col.measures': 'Måler',
      'guide.monitors.r1.f': 'Kun afsendelse',
      'guide.monitors.r1.v': 'connect → STARTTLS → AUTH → 250',
      'guide.monitors.r1.w': 'Beviser at serveren TOG imod beskeden. En fyldt kø, et omskrevet alias og et spamfilter tager alle imod først og taber bagefter.',
      'guide.monitors.r2.f': 'Round-trip',
      'guide.monitors.r2.v': 'samme afsendelse, derefter postkassen',
      'guide.monitors.r2.w': 'Måler leveringen hele vejen, fra din afsendelse til modtagerserverens eget ur. Prøvebeskeden sletter sig selv, når den er fundet.',
      'guide.monitors.r3.w': 'Gulvet under en målings eget interval. 15 minutter er et fornuftigt mail-interval; gulvet findes, så det her ikke kan blive til en mailbombe.',
      'guide.monitors.count.one': 'Én måling oprettet.',
      'guide.monitors.count.other': '{count} målinger oprettet.',
      'guide.monitors.none': 'Ingen målinger endnu. Mail-tjekket er det, man starter med — det er den fejl, ingen andre opdager.',
      'guide.monitors.domainsSet': 'Mail-prober må kun sende til: {domains}.',
      'guide.monitors.domainsOpen': 'Ingen modtagerdomæner er listet, så en mail-måling må sende til en hvilken som helst adresse. En administrator kan afgrænse det under Indstillinger → Service Assurance.',
      'guide.monitors.watch': 'Et afvist login på probens egen konto står som "fejlkonfigureret", ikke som et udfald — det siger intet om, hvorvidt rigtig mail kommer frem, og det vækker aldrig nogen.',
      'guide.monitors.note': 'En måling holder ikke øje med noget, før den har virket én gang, og mens den venter åbner et fejlende tjek ingenting — at sætte en op er ikke et udfald. Derefter: ét dårligt tjek er heller ikke et udfald: en fejl skal gentage sig, før der åbnes en hændelse. Et certifikat, der udløber, en record, der er væk, eller en adresse, der er listet, åbner én med det samme — de bliver ikke mere sande af at blive tjekket to gange.',
      'guide.unit.seconds': '{n} s',
      'guide.values.row.minInterval': 'Hvor ofte en måling højst må køre',
      'guide.values.row.mailDomains': 'Domæner en mail-probe må sende til (tom = alle)',
      'guide.values.row.monitorRetention': 'Hvor længe måleresultater gemmes',
      'guide.do.monitor.title': 'Opret mail-tjekket',
      'guide.do.monitor.help': 'Sender en besked gennem jeres mailserver med et fast interval og måler, hvad der skete. Det her opretter kun-afsendelse; åbn målingen bagefter for at tilføje postkassen og måle leveringen.',
      'guide.do.monitor.go': 'Opret måling',
      'guide.do.monitor.name': 'Navn',
      'guide.do.monitor.namePh': 'Kundemail',
      'guide.do.monitor.host': 'Mailserver',
